{
  "claims": [
    {
      "claim_text": "By default the kubelet sends HTTP/2 requests for HTTP probes.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that the default is HTTP/1.1, not HTTP/2.",
      "citations": [
        {
          "index": 0,
          "quote": "By default the `kubelet` sends HTTP/1.1 requests when executing an HTTP probe."
        }
      ]
    },
    {
      "claim_text": "Using HTTP/1.1 instead requires the H2CContainerProbe feature gate.",
      "verdict": "CONTRADICTED",
      "reasoning": "The feature gate is described as required for using HTTP/2 cleartext, while HTTP/1.1 is the default.",
      "citations": [
        {
          "index": 0,
          "quote": "If your application serves health endpoints only over HTTP/2 cleartext (h2c), you can add the `protocol` field to the `httpGet` field in the probe specification and specify a value of `HTTP2`. This requires the `H2CContainerProbe` feature gate to be enabled on both the `kube-apiserver` and the `kubelet`."
        }
      ]
    },
    {
      "claim_text": "A TCP probe considers the container healthy if it can open a socket on the given port.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly says the kubelet attempts to open a socket to the container on the specified port and considers the container healthy if it can establish a connection.",
      "citations": [
        {
          "index": 1,
          "quote": "With this configuration, the kubelet will attempt to open a socket to your container on the specified port. If it can establish a connection, the container is considered healthy, if it can't it is considered a failure."
        }
      ]
    },
    {
      "claim_text": "If the readiness probe fails, the kubelet restarts the container.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages describe readiness failure as making the Pod unready and withholding traffic, and readiness probes are used to avoid killing applications that are temporarily unable to serve traffic.",
      "citations": [
        {
          "index": 2,
          "quote": "If the readiness probe fails, the pod will be marked unready and will not receive traffic from any services."
        },
        {
          "index": 7,
          "quote": "In such cases, you don't want to kill the application, but you don't want to send it requests either. Kubernetes provides readiness probes to detect and mitigate these situations."
        }
      ]
    },
    {
      "claim_text": "gRPC probes connect over TLS by default.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that gRPC health endpoints are connected to over plaintext by default.",
      "citations": [
        {
          "index": 4,
          "quote": "By default the `kubelet` connects to gRPC health endpoints over plaintext."
        }
      ]
    },
    {
      "claim_text": "In TLS mode the kubelet verifies the server certificate.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that in TLS mode the kubelet uses InsecureSkipVerify and does not verify the server certificate.",
      "citations": [
        {
          "index": 5,
          "quote": "When `mode` is set to `TLS`, the `kubelet` connects over TLS with `InsecureSkipVerify` and does not verify the server certificate."
        }
      ]
    },
    {
      "claim_text": "The timeoutSeconds setting defaults to 1 second.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the `timeoutSeconds` setting defaults to 1s.",
      "citations": [
        {
          "index": 3,
          "quote": "the `timeoutSeconds` setting (which defaults to 1s)"
        }
      ]
    },
    {
      "claim_text": "If a startup probe never succeeds, the container keeps running.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that if the startup probe never succeeds, the container is killed after 300s.",
      "citations": [
        {
          "index": 6,
          "quote": "If the startup probe never succeeds, the container is killed after 300s and subject to the pod's `restartPolicy`."
        }
      ]
    },
    {
      "claim_text": "If a startup probe never succeeds, the container is never marked ready.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage states the container is killed if the startup probe never succeeds, but it does not state whether the container is marked ready or not in that case.",
      "citations": []
    },
    {
      "claim_text": "Readiness probes only start after the liveness probe has succeeded.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that readiness and liveness probes do not depend on each other to succeed.",
      "citations": [
        {
          "index": 8,
          "quote": "The readiness and liveness probes do not depend on each other to succeed."
        }
      ]
    }
  ]
}
